<?php
namespace App\Http\Controllers;
use App\Models\Business; use App\Models\Customer; use App\Models\Enquiry; use Illuminate\Http\Request;
class PublicFormController extends Controller {
    public function show(string $slug) { $business=Business::where('slug',$slug)->where('onboarding_completed',true)->firstOrFail(); return view('public.enquiry',compact('business')); }
    public function store(Request $request,string $slug) { $business=Business::where('slug',$slug)->where('onboarding_completed',true)->firstOrFail(); $data=$request->validate(['name'=>'required|string|max:120','email'=>'nullable|email|max:255','phone'=>'nullable|string|max:50','service_id'=>'nullable|integer','property_type'=>'nullable|string|max:100','property_address'=>'nullable|string|max:2000','preferred_date'=>'nullable|date','notes'=>'nullable|string|max:5000','website'=>'nullable|max:0']); if(!empty($data['service_id'])) abort_unless($business->services()->whereKey($data['service_id'])->exists(),404); $customer=Customer::firstOrCreate(['business_id'=>$business->id,'email'=>$data['email']??null,'phone'=>$data['phone']??null],['name'=>$data['name'],'address'=>$data['property_address']??null]); Enquiry::create(['business_id'=>$business->id,'customer_id'=>$customer->id,'service_id'=>$data['service_id']??null,'source'=>'public_form','property_type'=>$data['property_type']??null,'property_address'=>$data['property_address']??null,'preferred_date'=>$data['preferred_date']??null,'notes'=>$data['notes']??null]); return back()->with('status','Thanks — your enquiry has been sent. The business will be in touch shortly.'); }
}
